"""ARENA u08 的 10 道测验（沿用旧版题目，仅去掉解释里的位置引用）"""
from unitlib import Q
QUIZ = [
  Q('$f(x) = x^3$ 的导数是？', ['$x^2$', '$3x^2$', '$3x^3$', '$x^4/4$'], 1, "幂函数求导：$(x^n)' = nx^{n-1}$，所以 $3x^2$。$x^4/4$ 是积分（不定积分）的结果，不是导数。"),
  Q('$\\frac{d}{dx}\\ln(x^2 + 1)$ 等于？', ['$\\dfrac{2x}{x^2 + 1}$', '$\\dfrac{1}{x^2 + 1}$', '$2x\\ln(x^2+1)$', '$\\dfrac{1}{2x}$'], 0, '链式法则：外层 $\\ln u$ 的导数 $1/u$，乘内层 $x^2 + 1$ 的导数 $2x$。'),
  Q('$\\sigma(0) = 0.5$，Sigmoid 在 $x = 0$ 处的导数是？', ['0.5', '1', '0', '0.25'], 3, "$\\sigma'(0) = \\sigma(0)(1-\\sigma(0)) = 0.5 \\times 0.5 = 0.25$，这也是 Sigmoid 导数的最大值。"),
  Q('$f(x, y) = x^2y + 3y$，$\\dfrac{\\partial f}{\\partial y}$ 等于？', ['$2xy$', '$2x + 3$', '$x^2 + 3$', '$x^2y$'], 2, '对 $y$ 求偏导时把 $x$ 当常数：$x^2 \\cdot 1 + 3$。$2xy$ 是对 $x$ 的偏导数 $\\partial f / \\partial x$。'),
  Q('梯度 $\\nabla f$ 指向哪个方向？', ['$f$ 下降最快的方向', '$f$ 上升最快的方向', '$f$ 保持不变的方向', '总是指向原点'], 1, '梯度指向函数值**增加最快**的方向，所以梯度下降要沿 $-\\nabla f$ 走。'),
  Q('一阶泰勒展开 $f(\\mathbf{x}+\\mathbf{h}) \\approx f(\\mathbf{x}) + \\nabla f\\cdot\\mathbf{h}$ 说明了什么？', ['步长很小时，沿负梯度方向走一步函数值会下降；步长太大时近似会失效', '任意步长都能保证函数值下降', '梯度下降一定能找到全局最小值', '函数是线性的'], 0, '取 $\\mathbf{h} = -\\eta\\nabla f$，一阶项为 $-\\eta\\|\\nabla f\\|^2 < 0$。但这只是局部近似，学习率太大时高阶项不可忽略，可能反而变差。'),
  Q('均方误差 $L = \\frac{1}{2}(x - y)^2$ 对 $x$ 的导数是？', ['$(x - y)^2$', '$2(x - y)$', '$y - x$', '$x - y$'], 3, '$\\frac{1}{2} \\cdot 2(x - y) = x - y$。前面乘 $\\frac{1}{2}$ 就是为了约掉这个 2。'),
  Q('用均方误差训练时，如果模型输出 $x$ 比目标 $y$ **小**，梯度下降会怎样改变 $x$？', ['让 $x$ 变大，步子和误差大小成正比', '让 $x$ 变小', '不改变 $x$', '让 $x$ 变成 0'], 0, '$x < y$ 时 $\\partial L/\\partial x = x - y < 0$，沿负梯度走就是让 $x$ 增大，误差越大步子越大。'),
  Q('二元交叉熵中，真实标签 $y = 1$，模型给出的概率 $x$ 很接近 0。$\\partial L / \\partial x$ 会怎样？', ['接近 0，几乎不更新', '等于 1', '是一个绝对值非常大的负数，模型被强烈推动去增大 $x$', '是一个很大的正数'], 2, '$y = 1$ 时 $\\partial L/\\partial x = -1/x$，$x \\to 0$ 时趋向 $-\\infty$。「自信地答错」会被重罚。'),
  Q('BCE 损失配合 Sigmoid，对 logit $z$ 的梯度 $\\partial L / \\partial z$ 是？', ['$-y/\\sigma(z)$', '$\\sigma(z)(1-\\sigma(z))$', '$y - \\sigma(z)$', '$\\sigma(z) - y$'], 3, '链式法则后 $1/x$ 和 $x(1-x)$ 约掉，得到简洁的 $\\sigma(z) - y$：预测概率减去标签，有界且好算。注意符号：$y - \\sigma(z)$ 是它的相反数。'),
]
